-- Generated by Ergasterion from a product declaration. Do not edit by hand.
{{ config(materialized='table') }}

with
quarantined as (
    select
        decision_id,
        deal_external_identity,
        decision_outcome,
        decision_conditions,
        decision_actor,
        decision_decided_at,
        decision_rank,
        decision_is_final,
        violation_00,
        violation_01
    from {{ ref("investment__deal_decision_queue__checked") }}
),
violations as (
    select
        'decision_id_not_null' as rule_name,
        decision_id,
        deal_external_identity,
        decision_outcome,
        decision_conditions,
        decision_actor,
        decision_decided_at,
        decision_rank,
        decision_is_final
    from quarantined
    where violation_00

    union all

    select
        'decision_id_unique' as rule_name,
        decision_id,
        deal_external_identity,
        decision_outcome,
        decision_conditions,
        decision_actor,
        decision_decided_at,
        decision_rank,
        decision_is_final
    from quarantined
    where violation_01
)

select
    rule_name,
    decision_id,
    deal_external_identity,
    decision_outcome,
    decision_conditions,
    decision_actor,
    decision_decided_at,
    decision_rank,
    decision_is_final
from violations
